mapper.select:
select id, device_id, campus_id, reporter_id, worker_id, location, fault_description, status
from work_order
where id = #{id}

mapper.update:
update work_order
set status = #{nextStatus}
where id = #{id} and status = #{expectedStatus}

mapper.select:
select w.id as workOrderId, w.campus_id as campusId,
       w.device_id as deviceId, d.model as deviceModel, w.fault_description as faultDescription
from work_order w LEFT JOIN device d on w.device_id = d.id
where w.status = 'COMPLETED' and w.id > #{afterId}
ORDER BY w.id ASC
limit #{limit}
